class BrowserHistory {
    private final List<String> history=new ArrayList<>();
    private int current=0;
    public BrowserHistory(String homepage){
        history.add(homepage);
    }
    public void visit(String url){
        while(history.size()>current+1)history.remove(history.size()-1);
        history.add(url);
        current++;
    }
    public String back(int steps){
        current=Math.max(0,current-steps);
        return history.get(current);
    }
    public String forward(int steps){
        current=Math.min(history.size()-1,current+steps);
        return history.get(current);
    }
}

code.kotlin:
class BrowserHistory(homepage:String){
    private val history=mutableListOf(homepage);
    private var current=0;
    fun visit(url:String){
        while(history.size>current+1)history.removeAt(history.lastIndex);
        history.add(url);
        current++
    };
    fun back(steps:Int):String{
        current=maxOf(0,current-steps);
        return history[current]
    };
    fun forward(steps:Int):String{
        current=minOf(history.lastIndex,current+steps);
        return history[current]
    }
}

